package com.agriconnect.notification;import static org.assertj.core.api.Assertions.*;import java.util.*;import org.h2.jdbcx.JdbcDataSource;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.*;import org.springframework.jdbc.core.simple.JdbcClient;class NotificationConsumerTest{@Test void duplicateEventCreatesOneNotification(){JdbcDataSource ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:notify;MODE=PostgreSQL;DB_CLOSE_DELAY=-1");JdbcTemplate j=new JdbcTemplate(ds);j.execute("create table notifications(id bigint generated by default as identity,event_id uuid unique,recipient_user_id bigint,type varchar,title varchar,message varchar,reference_type varchar,reference_id varchar,read_at timestamp,created_at timestamp default current_timestamp)");j.execute("create table processed_events(event_id uuid primary key,processed_at timestamp default current_timestamp)");NotificationConsumer c=new NotificationConsumer(JdbcClient.create(ds));UUID id=UUID.randomUUID();Map<String,Object>e=Map.of("eventId",id,"eventType","OrderConfirmed","aggregateType","Order","aggregateId","1","payload",Map.of("buyerId",20));c.consume(e);c.consume(e);assertThat(j.queryForObject("select count(*) from notifications",Integer.class)).isEqualTo(1);}}
